mkdir -p /tmp/bot-check && cat > /tmp/bot-check/check.mjs <<'EOF'
import assert from "node:assert/strict";
import { onInbound, check } from "<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round6-heldout-c-haiku/work/ours-g5-3/bot.mjs";

const H = 60 * 60 * 1000;
const t0 = new Date("2026-10-23T09:00:00Z");
const at = (h) => new Date(t0.getTime() + h * H);
let n = 0;
const ok = (name, fn) => { fn(); n++; console.log("ok -", name); };
const allowed = (r) => assert.deepEqual(r, { allowed: true, rule: null });
const blocked = (r, rule) => assert.deepEqual(r, { allowed: false, rule });

let id = 0; const uid = () => `u${++id}`;

ok("never-written customer blocked for freeform and template", () => {
  const u = uid();
  blocked(check(u, "freeform", at(0)), "no-inbound-consent");
  blocked(check(u, "template", at(0)), "no-inbound-consent");
});

ok("fresh inbound: freeform and template allowed", () => {
  const u = uid(); onInbound(u, "my bill is wrong", at(0));
  allowed(check(u, "freeform", at(1)));
  allowed(check(u, "template", at(1)));
});

ok("freeform window: open at 23h59m, closed at 24h", () => {
  const u = uid(); onInbound(u, "hi", at(0));
  allowed(check(u, "freeform", new Date(at(0).getTime() + DAY_MS_MINUS(1))));
  blocked(check(u, "freeform", at(24)), "outside-24h-window");
  allowed(check(u, "template", at(48)));
});
function DAY_MS_MINUS(m) { return 24 * H - m * 60 * 1000; }

ok("out-of-order inbound keeps the latest timestamp for the window", () => {
  const u = uid(); onInbound(u, "hi", at(10)); onInbound(u, "old", at(0));
  allowed(check(u, "freeform", at(30)));
});

ok("now before last inbound blocks freeform", () => {
  const u = uid(); onInbound(u, "hi", at(5));
  blocked(check(u, "freeform", at(1)), "now-before-last-inbound");
});

const stopForms = ["stop", " STOP ", "Stop!!", "stop.", "🛑 stop 🛑", "ｓｔｏｐ", "stop​", "Stop Texting Me", "don't text me", "STOPALL", "unsubscribe", "Cancel", "quit", "end"];
for (const form of stopForms) {
  ok(`opt-out keyword ${JSON.stringify(form)} blocks everything`, () => {
    const u = uid(); onInbound(u, "hello", at(0)); onInbound(u, form, at(1));
    blocked(check(u, "freeform", at(2)), "opted-out");
    blocked(check(u, "template", at(2)), "opted-out");
  });
}

const ordinary = ["I can't stop thinking about my bill", "stop by the store later", "please stop", "cancel my appointment on Friday", "start my plan", "yes I want the upgrade please"];
for (const msg of ordinary) {
  ok(`ordinary sentence ${JSON.stringify(msg)} is not an opt-out`, () => {
    const u = uid(); onInbound(u, msg, at(0));
    allowed(check(u, "freeform", at(1)));
  });
}

ok("START after STOP restores both types", () => {
  const u = uid(); onInbound(u, "STOP", at(0));
  blocked(check(u, "template", at(1)), "opted-out");
  onInbound(u, "  start. ", at(2));
  allowed(check(u, "template", at(3)));
  allowed(check(u, "freeform", at(3)));
});

ok("UNSTOP and YES also restore", () => {
  const a = uid(); onInbound(a, "stop", at(0)); onInbound(a, "UNSTOP", at(1));
  allowed(check(a, "template", at(2)));
  const b = uid(); onInbound(b, "STOP", at(0)); onInbound(b, "yes!", at(1));
  allowed(check(b, "template", at(2)));
});

ok("STOP after START blocks again", () => {
  const u = uid(); onInbound(u, "stop", at(0)); onInbound(u, "start", at(1)); onInbound(u, "stop", at(2));
  blocked(check(u, "template", at(3)), "opted-out");
});

ok("ordinary message does not lift an opt-out", () => {
  const u = uid(); onInbound(u, "stop", at(0)); onInbound(u, "start my plan", at(1));
  blocked(check(u, "template", at(2)), "opted-out");
});

ok("out-of-order START older than STOP does not lift the opt-out", () => {
  const u = uid(); onInbound(u, "STOP", at(5)); onInbound(u, "START", at(2));
  blocked(check(u, "template", at(6)), "opted-out");
});

ok("out-of-order STOP older than START does not opt out", () => {
  const u = uid(); onInbound(u, "START", at(5)); onInbound(u, "STOP", at(2));
  allowed(check(u, "template", at(6)));
});

ok("null/undefined text counts as inbound (media message)", () => {
  const u = uid(); onInbound(u, null, at(0));
  allowed(check(u, "freeform", at(1)));
});

ok("invalid check arguments fail closed", () => {
  const u = uid(); onInbound(u, "hi", at(0));
  blocked(check("", "template", at(1)), "invalid-input");
  blocked(check(u, "email", at(1)), "invalid-input");
  blocked(check(u, "template", "2026-10-23"), "invalid-input");
  blocked(check(u, "template", new Date("nope")), "invalid-input");
});

ok("invalid onInbound arguments throw", () => {
  assert.throws(() => onInbound("", "hi", at(0)), TypeError);
  assert.throws(() => onInbound("x", 42, at(0)), TypeError);
  assert.throws(() => onInbound("x", "hi", "2026-10-23"), TypeError);
});

console.log(`\n${n} checks passed`);
EOF
cd /tmp/bot-check && node check.mjs && node -e 'import("<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round6-heldout-c-haiku/work/ours-g5-3/bot.mjs").then(m=>console.log(Object.keys(m)))'
